@startuml

class Doctor {
  + practitionerNumber : string
  + fullName : string
  + address : string
  + phoneNumber : string
  + signature : string
}

class Patient {
  + healthNumber : string
  + firstName : string
  + lastName : string
  + dateOfBirth : date
  + address : string
  + phoneNumber : string
}

class Requisition {
  + validFrom : date
  + repetitionCount : int
  + repetitionInterval : string
}

class Test {
  + duration : int
}

class TestResult {
  + result : boolean
  + report : string
}

class Appointment {
  + confirmationNumber : string
  + date : date
  + startTime : time
  + endTime : time
}

class Lab {
  + address : string
  + businessHours : string
  + registrationNumber : string
  + changeCancellationFee : float
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : receives
Requisition "1" *-- "1..*" Test : contains
Doctor "1" -- "*" TestResult : views
Patient "1" -- "*" TestResult : views
Patient "1" -- "0..1" Appointment : makes
Requisition "1" -- "0..1" Appointment : for
Lab "1" -- "*" Appointment : hosts
Lab "1" -- "*" Test : offers

@enduml

